const replaceHeight = (declaration: string): string => {
    const match = declaration.match(/^(\s*height\s*:\s*)([\s\S]*)$/i);

    if (!match || !/vh/i.test(match[2])) {
        return declaration;
    }

    const important = match[2].match(/\s*!important\s*$/i)?.[0] || '';
    return `${match[1]}auto${important}`;
};

const replaceViewportHeights = (style: string): string => {
    let result = '';
    let start = 0;
    let quote = '';
    let depth = 0;
    let inComment = false;

    for (let index = 0; index < style.length; index++) {
        const character = style[index];
        const next = style[index + 1];

        if (character === ';' && !quote && !inComment && depth === 0) {
            result += replaceHeight(style.slice(start, index));
            result += ';';
            start = index + 1;
        } else if (inComment) {
            if (character === '*' && next === '/') {
                inComment = false;
                index++;
            }
        } else if (quote) {
            if (character === '\\') {
                index++;
            } else if (character === quote) {
                quote = '';
            }
        } else if (character === '/' && next === '*') {
            inComment = true;
            index++;
        } else if (character === '"' || character === "'") {
            quote = character;
        } else if (character === '(') {
            depth++;
        } else if (character === ')' && depth > 0) {
            depth--;
        }
    }

    return result + replaceHeight(style.slice(start));
};

export const transformStyleAttributes = (document: Element): void => {
    const elements = [document, ...document.querySelectorAll('[style]')];

    elements.forEach((element) => {
        const style = element.getAttribute('style');

        if (style === null) {
            return;
        }

        const nextStyle = replaceViewportHeights(style);

        if (nextStyle !== style) {
            element.setAttribute('style', nextStyle);
        }
    });
};
import { transformStyleAttributes } from '../transformStyleAttributes';

describe('transformStyleAttributes', () => {
    it('replaces viewport heights on the root and descendants without changing other styles', () => {
        const root = document.createElement('div');
        root.setAttribute('style', 'height: 100vh; color: red');
        root.innerHTML = `
            <section style="height: calc(50vh + 10px) !important; background: proton-url(https://example.com/a.png)">
                <div style="height: 20px; min-height: 25vh; width: 30vh"></div>
            </section>
        `;

        transformStyleAttributes(root);

        const section = root.querySelector('section') as HTMLElement;
        const child = root.querySelector('section div') as HTMLElement;

        expect(root.style.height).toBe('auto');
        expect(root.style.color).toBe('red');
        expect(section.style.height).toBe('auto');
        expect(section.style.getPropertyPriority('height')).toBe('important');
        expect(section.getAttribute('style')).toContain('proton-url');
        expect(child.style.height).toBe('20px');
        expect(child.style.minHeight).toBe('25vh');
        expect(child.style.width).toBe('30vh');
    });

    it('does not treat semicolons inside other values as declaration boundaries', () => {
        const root = document.createElement('div');
        root.setAttribute(
            'style',
            'background: proton-url("https://example.com/a;v=1"); height: 40VH; content: ";height: 60vh"'
        );

        transformStyleAttributes(root);

        expect(root.getAttribute('style')).toBe(
            'background: proton-url("https://example.com/a;v=1"); height: auto; content: ";height: 60vh"'
        );
    });
});

